insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('e076f077-fbb9-4ad8-a544-d71a520ac030', 'trabajo', 'practica', 'La idea que casi se pierde',
   'Renata propuso adelantar la entrega dos días y hubo tres segundos de silencio. Entonces habló Adriana: «Secundo lo de Renata, y explico por qué: nos deja margen si falla el proveedor». La propuesta salió adelante.',
   'Yo también estoy de acuerdo con lo que dijo.', 'Secundo lo de Renata, y explico por qué.', 1),
  ('e076f077-fbb9-4ad8-a544-d71a520ac030', 'familia', 'emocional', 'Turnos en la casa del pueblo',
   'Nadie quería abrir el asunto de los turnos hasta que la hermana menor propuso un calendario. Su primo levantó la mano: «Yo la secundo, y me pido agosto». Esa misma tarde hubo calendario colgado en la nevera.',
   'A mí me parece bien lo que dice ella.', 'Yo la secundo, y me pido agosto.', 2),
  ('e076f077-fbb9-4ad8-a544-d71a520ac030', 'social', 'social', 'Asamblea del edificio',
   'El portero propuso cambiar la hora de la basura y nadie reaccionó. Un vecino del cuarto dijo: «Lo secundo; con mi horario me viene mejor». Otras dos manos se levantaron detrás y el cambio quedó aprobado.',
   'Pues yo digo lo mismo que él.', 'Lo secundo; con mi horario me viene mejor.', 3);

