insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('ff5901fe-fddd-491d-b611-e946d28ec70f', 'trabajo', 'practica', 'Los correos de medianoche',
   'El equipo tenía una costumbre mala y nadie quería señalar a quien la empezó. Renata lo planteó así: «Voy a aludir a un hábito, no a una persona: los correos de medianoche». Nadie se sintió atacado y la costumbre cambió.',
   'No quiero decir nombres, pero ya se entiende a qué me refiero.', 'Voy a aludir a un hábito, no a una persona.', 1),
  ('ff5901fe-fddd-491d-b611-e946d28ec70f', 'familia', 'emocional', 'Lo de tu tío',
   'Mi abuela tenía una fórmula para todo lo incómodo: «lo de tu tío». Nunca daba detalles y todos entendíamos. Años después mi madre me lo explicó: «Aludía a la mudanza para no hacerle daño a nadie en la mesa».',
   'Hablaba de eso sin decirlo nunca.', 'Aludía a la mudanza para no hacer daño.', 2),
  ('ff5901fe-fddd-491d-b611-e946d28ec70f', 'entrevista', 'social', 'Sin decir el cliente',
   'Adriana quería contar su mejor proyecto, pero había firmado un acuerdo de confidencialidad. Resolvió así: «Puedo aludir al sector y al tamaño, no al cliente». Contó el problema, la solución y los números, y la entrevistadora quedó satisfecha.',
   'Es de una empresa que no puedo nombrar.', 'Puedo aludir al sector y al tamaño.', 3);

