insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('4526094d-785a-45d4-9cab-7bc8401c714e', 'trabajo', 'practica', 'Una idea al cierre',
   'La presentación tenía dieciocho diapositivas y Marta sabía que nadie recordaría dieciocho cosas. Cerró así: «Si solo se llevan una frase, quiero recalcar esta: el plazo es el 30 y no se mueve». Tres semanas después seguían citando la fecha.',
