insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('4cbb0c48-602e-4c31-8b6c-11660597005f', 'trabajo', 'practica', 'Doscientas personas quietas',
   'Marta tenía quince minutos y un tema difícil. En vez de abrir con la gráfica, contó qué le dijo su primer cliente en 2015. «Nos cautivó desde la primera frase», comentó alguien al salir. Nadie sacó el móvil en quince minutos.',
