insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('f5d9ffd4-3596-4582-a437-179ee980d799', 'entrevista', 'practica', 'Quince minutos sin papel',
   'Adriana había llevado el currículo impreso por costumbre, pero lo dejó bocabajo. «Le cuento mi trayectoria en tres pasos: almacén, compras y ahora proveedores». Tardó quince minutos y no leyó ni una línea.',
   'Le cuento un poco lo que he ido haciendo.', 'Le cuento mi trayectoria en tres pasos.', 1),
  ('f5d9ffd4-3596-4582-a437-179ee980d799', 'familia', 'emocional', 'De aprendiz a encargado',
   'Mi abuelo resume cuarenta años en once palabras: entró de aprendiz con catorce y salió de encargado con cincuenta y cuatro. «Toda mi trayectoria cabe en una frase», dice, y se ríe. Luego cuenta la parte larga, que dura dos cafés.',
   'Todo lo que hice cabe en una frase.', 'Toda mi trayectoria cabe en una frase.', 2),
  ('f5d9ffd4-3596-4582-a437-179ee980d799', 'social', 'social', 'El premio de la librera',
   'La asociación del barrio premió a la librera de la esquina, que abrió en 1985 y sigue abriendo a las nueve. En la placa pusieron una sola línea: «Por una trayectoria de cuarenta años». Ella dijo gracias y volvió al mostrador.',
   'Por todos estos años de trabajo.', 'Por una trayectoria de cuarenta años.', 3);

