insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('28b9d9e9-3526-4520-9ff7-3281e8f8bdc0', 'trabajo', 'practica', 'Dos preguntas antes',
   'Patricia quería pedir una semana libre en plena entrega. En vez de escribir el correo, preguntó primero cómo iba el calendario. «Déjame tantear el terreno», le dijo a su compañera. El jueves ya sabía qué semana pedir.',
   'Voy a ver cómo está la cosa primero.', 'Déjame tantear el terreno.', 1),
  ('28b9d9e9-3526-4520-9ff7-3281e8f8bdc0', 'familia', 'emocional', 'La cena del domingo',
   'Óscar llevaba semanas queriendo contarle a su madre que se mudaba de ciudad. Empezó preguntándole por su hermana, por el trabajo, por el barrio. Luego se rio: «Perdona, mamá, te estoy tanteando. Me voy a vivir a otro sitio».',
   'Perdona, te estoy midiendo el ánimo.', 'Perdona, te estoy tanteando.', 2),
  ('28b9d9e9-3526-4520-9ff7-3281e8f8bdc0', 'social', 'social', 'El regalo compartido',
   'Renata no sabía si el grupo querría poner dinero para el regalo. Escribió un mensaje corto y sin cifras, solo para ver quién respondía. «Estoy tanteando», avisó. Contestaron cinco personas en media hora y salió a cuenta.',
   'Solo estoy viendo qué dice la gente.', 'Estoy tanteando al grupo.', 3);

