insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('bbe9898a-f790-48d6-87e6-361822b51333', 'familia', 'emocional', 'Veinte minutos al día',
   'Ignacio llevaba ocho meses estudiando al volver de trabajar, sin contárselo a nadie. Cuando aprobó, su hija le preguntó cómo lo había hecho. «Con constancia, no con tiempo libre», contestó él, y guardó los apuntes en una caja.',
   'Simplemente no lo dejé nunca.', 'Lo saqué con constancia.', 1),
  ('bbe9898a-f790-48d6-87e6-361822b51333', 'social', 'social', 'El grupo de los martes',
   'Cinco vecinos empezaron a salir a andar juntos en octubre. En febrero quedaban tres. Rosa escribió en el chat: «Brindo por la constancia de los martes, llueva o no». Aquella noche volvieron a aparecer cinco.',
   'Lo bueno es que no fallamos.', 'Brindo por la constancia de los martes.', 2),
  ('bbe9898a-f790-48d6-87e6-361822b51333', 'trabajo', 'practica', 'El informe mensual',
   'Nadie leía el resumen que Óscar mandaba cada mes. Al año y medio, una responsable nueva lo usó para entender el área entera en una tarde. Le escribió: «Tu constancia me acaba de ahorrar dos semanas».',
   'Menos mal que lo mandaste siempre.', 'Tu constancia me ahorró dos semanas.', 3);

