insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('963da377-c4db-44d6-afb9-19824efb3b51', 'social', 'social', 'La cena del viernes',
   'A Lorena la invitaron a una cena el mismo día que había prometido descansar. Contestó en dos líneas: «Me hace mucha ilusión, pero esta vez lo declino; avísame de la próxima». Nadie se molestó y la próxima llegó en quince días.',
