insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('4aada36c-979d-4baf-8755-134dffff0d05', 'familia', 'emocional', 'La semana de las cajas',
   'Isabel llevaba siete días entre cajas, llamadas y comidas rápidas. Su hermano le escribió para reñirle y ella contestó antes: «Con el ajetreo de la mudanza no te llamé; el domingo te cuento todo». La llamó el sábado.',
   'Con tanto lío no te llamé.', 'Con el ajetreo de la mudanza no te llamé.', 1),
  ('4aada36c-979d-4baf-8755-134dffff0d05', 'social', 'social', 'La fiesta del barrio',
   'Óscar se ofreció a montar las mesas y acabó también con la música y el hielo. Al final del día se sentó en un escalón y se rio: «Qué ajetreo, y qué bien ha salido». Tres vecinos se sentaron con él.',
   'Qué día de locos, pero ha salido bien.', 'Qué ajetreo, y qué bien ha salido.', 2),
  ('4aada36c-979d-4baf-8755-134dffff0d05', 'trabajo', 'practica', 'Antes de la apertura',
   'Media hora antes de abrir, Renata vio a todo el equipo cruzándose por el pasillo. En vez de acelerarlo más, dijo en voz alta: «Con este ajetreo nos vamos a chocar; hagamos una vuelta por turnos». Abrieron a la hora.',
   'Hay mucho movimiento aquí dentro.', 'Con este ajetreo nos vamos a chocar.', 3);

