insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('8edc702d-9522-45e1-bc69-0b0ad241cb7c', 'social', 'social', 'La cola del cine',
   'Adriana se giró y vio a una compañera de la universidad a la que no veía en seis años. «¡Qué fuerte, coincidimos aquí!», dijo. Entraron a la misma sesión y salieron con el teléfono de la otra.',
