insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('ffb00d27-f805-4949-aa53-cea166da0dbf', 'trabajo', 'practica', 'La ronda que se destrabó',
   'Llevaban cuatro reuniones en el mismo punto. Andrea puso las cartas boca arriba: «Hago una concesión: acepto tu fecha. A cambio, quiero el pago en dos partes». El otro lado se miró un segundo y aceptó. El contrato se firmó el jueves.',
   'Yo pongo de mi parte, pero tú también.', 'Hago una concesión: acepto tu fecha.', 1),
  ('ffb00d27-f805-4949-aa53-cea166da0dbf', 'familia', 'emocional', 'El turno del coche',
   'La discusión por el coche duraba ya tres domingos. Joaquín cambió el tono: «Voy a hacerte una concesión y no la voy a usar en tu contra: quédatelo en agosto. Pero en diciembre es mío». Su hermana se rio y dijo que sí.',
   'Está bien, yo cedo esta vez.', 'Voy a hacerte una concesión, y no la usaré en tu contra.', 2),
  ('ffb00d27-f805-4949-aa53-cea166da0dbf', 'entrevista', 'social', 'El horario y el sueldo',
   'La oferta llegó con menos dinero del esperado. Leonor respondió con calma: «Puedo hacer una concesión en el sueldo si entramos a las diez». La responsable anotó y dijo que lo consultaba. Al día siguiente había acuerdo.',
   'Puedo ceder algo si me dan algo a cambio.', 'Puedo hacer una concesión en el sueldo.', 3);

