insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('3a84e86d-d99d-4de0-9433-68f6d7779aef', 'trabajo', 'practica', 'El día de lluvia',
   'Faltaba una semana para el evento y el cielo no ayudaba. Victoria repasó el presupuesto y preguntó: «¿Contemplamos una carpa por si llueve?». Nadie lo había pensado. Llovió, hubo carpa, y el cliente lo contó durante meses.',
   '¿Y si llueve? Habría que tenerlo en cuenta.', '¿Contemplamos una carpa por si llueve?', 1),
  ('3a84e86d-d99d-4de0-9433-68f6d7779aef', 'familia', 'emocional', 'El reparto de agosto',
   'El calendario de vacaciones siempre acababa en discusión. Ramiro propuso otra cosa: «Vamos a contemplar los dos casos: si la abuela viene, y si no viene». Escribieron las dos versiones en la nevera. Ese agosto nadie tuvo que improvisar.',
   '¿Y si al final no viene? No lo hemos pensado.', 'Vamos a contemplar los dos casos.', 2),
  ('3a84e86d-d99d-4de0-9433-68f6d7779aef', 'social', 'social', 'La cuota del club',
   'El grupo de la cancha discutía la cuota nueva. Olga levantó la mano: «¿Contemplamos a quien solo juega un mes al año?». Se hizo un silencio corto y salió una cuota reducida. Volvieron tres personas que se habían ido.',
   '¿Y los que juegan poco? Nadie los tuvo en cuenta.', '¿Contemplamos a quien solo juega un mes?', 3);

