insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('79655073-9b60-4e3e-aa11-dd80f5bb25b1', 'trabajo', 'practica', 'Medio año de palabra',
   'Llevaban seis meses colaborando sin un solo papel. Cuando cambió la jefa, Rocío se adelantó: «Propongo formalizar lo que ya hacemos: mismas condiciones, con fecha y firma». Tardaron dos días. La jefa nueva llegó y no hubo nada que renegociar.',
   'Habría que dejar esto por escrito.', 'Propongo formalizar lo que ya hacemos.', 1),
  ('79655073-9b60-4e3e-aa11-dd80f5bb25b1', 'familia', 'emocional', 'El piso de los primos',
   'Los tres primos compartían el piso del pueblo sin normas escritas. Después del verano tenso, Mariana propuso: «Vamos a formalizar los turnos: un papel de media página, nada más». Nadie se ofendió, y el verano siguiente fue el mejor en años.',
   'Deberíamos poner esto en claro de una vez.', 'Vamos a formalizar los turnos.', 2),
  ('79655073-9b60-4e3e-aa11-dd80f5bb25b1', 'entrevista', 'social', 'Lo que se dijo en la sala',
   'Le prometieron revisión de sueldo a los seis meses. Álvaro sonrió y preguntó: «¿Podemos formalizar esa revisión en el contrato?». La responsable dudó un segundo y dijo que sí. Aquella frase valió más que toda la entrevista.',
   '¿Eso lo podemos dejar por escrito?', '¿Podemos formalizar esa revisión en el contrato?', 3);

