insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('0bddeaba-af5a-403d-93d1-696fd580d4f0', 'trabajo', 'practica', 'Las guardias de diciembre',
   'El calendario de guardias siempre acababa igual: los mismos cubrían las peores fechas. Irene propuso otra cosa: «Hagamos un reparto equitativo: quien cubrió Navidad el año pasado elige primero este año». Nadie protestó, y diciembre dejó de ser un problema.',
   'Vamos a repartirlo de forma justa.', 'Hagamos un reparto equitativo.', 1),
  ('0bddeaba-af5a-403d-93d1-696fd580d4f0', 'familia', 'emocional', 'Los gastos del piso',
   'Uno de los tres ganaba la mitad que los otros dos y callaba cada mes. Patricia lo dijo por él: «Partir en tres no es equitativo. Propongo repartir según lo que gana cada uno». Hubo un silencio incómodo y luego un alivio evidente.',
   'No es justo que paguemos lo mismo.', 'Partir en tres no es equitativo.', 2),
  ('0bddeaba-af5a-403d-93d1-696fd580d4f0', 'social', 'social', 'El alquiler de la furgoneta',
   'Cuatro amigos, una furgoneta y kilómetros muy distintos. Simón sacó el móvil: «Lo equitativo es pagar por kilómetro, no por cabeza». Hicieron la cuenta en un minuto. Dos pagaron menos y nadie se sintió engañado.',
   'Repartámoslo de forma justa, no a partes iguales.', 'Lo equitativo es pagar por kilómetro.', 3);

