insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('e7c95923-9539-4709-ad5d-40a0292bee02', 'trabajo', 'practica', 'La firma también',
   'Marcos llevaba tres meses ahogado. Su jefa lo llamó y le dijo algo sencillo: «Voy a delegar el trato con imprenta en ti. Incluye decidir el precio hasta dos mil euros». Marcos entendió que esta vez iba en serio, y dejó de preguntar por cada detalle.',
   'Te paso el trato con imprenta.', 'Voy a delegar el trato con imprenta en ti.', 1),
  ('e7c95923-9539-4709-ad5d-40a0292bee02', 'familia', 'emocional', 'La lista de la compra',
   'Su madre corregía cada compra que hacía él. Un sábado, Vicente se sentó a su lado: «Si vas a delegar la compra, delégala entera. Si no, la hago contigo y ya está». Ella lo pensó una semana. Desde entonces no volvió a revisar el tique.',
   'O me lo dejas a mí, o lo hacemos juntos.', 'Si vas a delegar la compra, delégala entera.', 2),
  ('e7c95923-9539-4709-ad5d-40a0292bee02', 'social', 'social', 'La fiesta de los cuarenta',
   'Organizar la fiesta estaba acabando con Natalia. En el grupo escribió: «Delego la música en Samuel y la comida en Emma. Deciden ellos, yo no opino». Nadie discutió la lista de canciones, y ella llegó descansada a su propia fiesta.',
   'Que se encarguen ellos de la música y la comida.', 'Delego la música en Samuel y la comida en Emma.', 3);

