insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('7733024d-0f8f-4876-92eb-12d4dee68193', 'trabajo', 'practica', 'El proyecto que salió regular',
   'El resultado no fue bueno y todos lo sabían. Aun así, su responsable dijo algo en la reunión final: «El proyecto salió regular. Camila fue diligente: entregó a tiempo y avisó de cada problema». Camila entendió que el fallo no era suyo, y siguió avisando.',
   'Ella respondió rápido y bien, eso sí.', 'Camila fue diligente de principio a fin.', 1),
  ('7733024d-0f8f-4876-92eb-12d4dee68193', 'familia', 'emocional', 'Los papeles del abuelo',
   'La herencia llevaba dos años parada entre cuatro hermanos. Uno se ocupó sin decirlo: pedía turnos, traía firmas, recordaba fechas. Cuando por fin acabó, su hermana lo dijo en la comida: «Si no llega a ser por lo diligente que ha sido Álvaro, seguimos igual».',
   'Menos mal que él lo hizo todo rápido.', 'Si no llega a ser por lo diligente que ha sido…', 2),
  ('7733024d-0f8f-4876-92eb-12d4dee68193', 'entrevista', 'social', 'La pregunta sobre el equipo',
   'Le preguntaron a Blanca qué buscaba en un compañero. No dijo brillante ni creativo: «Busco gente diligente. Prefiero a quien avisa el martes de que algo no llega, antes que a quien me sorprende el viernes». La mesa asintió a la vez.',
   'Busco gente que responda rápido y bien.', 'Busco gente diligente.', 3);

