insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('5a59213d-4fcc-4cb4-8390-f2c44b9a391c', 'trabajo', 'practica', 'La cifra de la diapositiva',
   'A mitad de la presentación alguien le enseñó el dato real. Julia paró: «Rectifico: la cifra que acabo de decir es del trimestre anterior. La buena es esta». Nadie recordó el fallo; todos recordaron que lo corrigió en el momento.',
   'Perdón, me equivoqué con ese número.', 'Rectifico: el número bueno es este.', 1),
  ('5a59213d-4fcc-4cb4-8390-f2c44b9a391c', 'familia', 'emocional', 'Lo que dijo del novio',
   'Había soltado una frase dura sobre el novio de su hija y se quedó dándole vueltas dos días. El domingo, en la cocina, lo dijo entero: «Rectifico lo que dije el jueves. Hablé sin conocerlo». Su hija no contestó, pero lo invitó a la cena siguiente.',
   'Me pasé el otro día, lo retiro.', 'Rectifico lo que dije el jueves.', 2),
  ('5a59213d-4fcc-4cb4-8390-f2c44b9a391c', 'social', 'social', 'La discusión del grupo',
   'En el chat, Andrés había acusado a alguien de no pagar su parte. Media hora después apareció el recibo. Escribió sin excusas: «Rectifico. El pago estaba hecho y me equivoqué de mes. Perdón, Sara». El grupo siguió como si nada, que es justo lo que hace un buen grupo.',
   'Perdón, me confundí, retiro lo dicho.', 'Rectifico: el pago estaba hecho.', 3);

