insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('f5e7de35-f617-4464-8bf6-948d4ce41643', 'trabajo', 'practica', 'Sin mayúsculas',
   'Otilia necesitaba una firma antes del viernes y sabía que las mayúsculas ya no funcionaban con nadie. Escribió: «El plazo es apremiante: sin tu firma el lunes, la entrega se va dos semanas». Firmaron el jueves por la mañana.',
