insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('a4019d66-ba86-4933-b4b0-93bdc24c5472', 'trabajo', 'practica', 'La frase del jueves',
   'Otilia presentó doce diapositivas y solo repitió una idea: «Cada correo sin contestar cuesta once minutos a otra persona». Nadie aplaudió. El martes siguiente, dos equipos habían cambiado su forma de responder. Aquella frase caló.',
   'Creo que gustó la presentación, ¿no?', 'Aquella frase caló: lo vi el martes.', 1),
  ('a4019d66-ba86-4933-b4b0-93bdc24c5472', 'familia', 'emocional', 'Tú nunca preguntas',
   'La discusión con su hija duró una hora y no sirvió de nada. Lo que le caló fue una frase suelta del final: «Tú nunca preguntas». Gonzalo la recordó toda la semana, y el domingo empezó la llamada preguntando.',
   'Se me quedó grabado lo que me dijo.', 'Esa frase me caló toda la semana.', 2),
  ('a4019d66-ba86-4933-b4b0-93bdc24c5472', 'entrevista', 'practica', 'Lo que recordaron de mí',
   'Ámbar contó un solo ejemplo y lo repitió al despedirse. Dos semanas después la llamaron y le dijeron: «Seguimos hablando de tu caso del almacén». Había preparado seis historias y con una que calara fue suficiente.',
   'Conté un montón de cosas, a ver si alguna les sonó.', 'Con que calara una historia, bastaba.', 3);

