insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('1756a4b4-a6e8-44fc-a0af-66ed80db4fcc', 'trabajo', 'practica', 'Hechos arriba, propuesta abajo',
   'Otilia dividió su correo en dos bloques. Arriba: «Constato tres cosas: los plazos se cumplen, las quejas bajaron a la mitad y seguimos sin manual». Abajo, una propuesta de tres líneas. Nadie discutió la primera parte y el debate fue corto.',
   'Yo creo que va mejor, ¿no?', 'Constato tres cosas.', 1),
  ('1756a4b4-a6e8-44fc-a0af-66ed80db4fcc', 'familia', 'emocional', 'La casa del pueblo',
   'Su madre temía encontrarse el tejado hundido tras el invierno. Ivo subió con una escalera, miró despacio y la llamó: «Constato que aguantó; solo faltan dos tejas». Ella respiró por primera vez en tres meses.',
   'Yo lo veo bien, pero vete a saber.', 'Constato que aguantó.', 2),
  ('1756a4b4-a6e8-44fc-a0af-66ed80db4fcc', 'entrevista', 'practica', 'Antes de opinar',
   'Le preguntaron qué mejoraría del equipo al que iba a entrar. Amalia no repartió juicios: «Desde fuera solo puedo constatar dos cosas: el equipo publica muy rápido y responde poco en redes. Lo demás tendría que verlo por dentro». Le ofrecieron el puesto.',
   'Pues yo cambiaría un montón de cosas.', 'Desde fuera solo puedo constatar dos cosas.', 3);

