insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('240a13a3-5565-46d7-9a5c-ea51a357735f', 'trabajo', 'practica', 'Tres líneas y ninguna pregunta',
   'El proyecto llevaba semanas de correos cruzados. Otilia escribió: «Tú cierras el texto el martes, yo maqueto el miércoles, publicamos el jueves a las diez». No hubo respuestas, y eso fue la mejor señal. «Qué nítido», le dijeron después.',
   'A ver si nos aclaramos con las fechas.', 'Qué nítido quedó.', 1),
  ('240a13a3-5565-46d7-9a5c-ea51a357735f', 'familia', 'emocional', 'El horno de mi padre',
   'Su padre llamaba cada vez que intentaba usar el horno nuevo. Delia le escribió cinco pasos y una foto con el mando señalado. Esa semana no sonó el teléfono, y el domingo él dijo: «Con tus instrucciones tan nítidas, hasta yo puedo».',
   'Te lo explico otra vez, pero por teléfono.', 'Te lo dejo nítido en cinco pasos.', 2),
  ('240a13a3-5565-46d7-9a5c-ea51a357735f', 'entrevista', 'practica', 'Dos frases sobre el sueldo',
   'Ivo llevaba meses evitando la pregunta del dinero. Esta vez la dejó nítida: «Busco una cifra entre estas dos y valoro los días desde casa». La conversación duró cuatro minutos y salió sabiendo a qué atenerse.',
   'Pues no sé, lo que sea razonable.', 'Lo dejo nítido: busco una cifra entre estas dos.', 3);

