insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('36fa09c3-97e1-4424-9ffd-663725c66020', 'trabajo', 'practica', 'Sin introducción',
   'El documento de Otilia empezaba con media página sobre la historia del proyecto. La borró y escribió una línea: «Prescindo del contexto; si hace falta, está en el anexo». La decisión llegó en la reunión siguiente y nadie pidió el anexo.',
   'Bueno, primero te cuento de dónde viene todo esto.', 'Prescindo del contexto: vamos a la decisión.', 1),
  ('36fa09c3-97e1-4424-9ffd-663725c66020', 'social', 'social', 'La cena sin postre',
   'Faltaban dos horas y la lista de la compra no cabía en el presupuesto. Leandro miró la lista y dijo: «Prescindimos del postre y ponemos fruta; nadie se va a acordar mañana». Sobró comida, sobró dinero y nadie echó nada en falta.',
   'Habrá que quitar algo, no sé qué.', 'Prescindimos del postre.', 2),
  ('36fa09c3-97e1-4424-9ffd-663725c66020', 'entrevista', 'practica', 'Dos minutos, una historia',
   'Ámbar tenía siete años de trabajo y dos minutos para contarlos. Empezó avisando: «Voy a prescindir de los primeros empleos y te cuento el proyecto que me enseñó lo que sé». Le preguntaron por ese proyecto durante veinte minutos.',
   'Empiezo por el principio, aunque sea largo.', 'Voy a prescindir de los primeros empleos.', 3);

