insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('6064f214-1ddb-49fa-b87e-0ef6dbe15fd2', 'trabajo', 'practica', 'Tres delante, el resto en octubre',
   'La lista de Otilia tenía veinte peticiones y todas llegaban con la palabra urgente. Escribió un correo corto: «He priorizado: estas tres salen este mes, las demás en octubre. Si alguna no puede esperar, dímelo hoy». Solo una persona respondió, y tenía razón.',
   'Voy a intentar hacerlo todo, a ver si llego.', 'He priorizado: estas tres salen este mes.', 1),
  ('6064f214-1ddb-49fa-b87e-0ef6dbe15fd2', 'familia', 'emocional', 'Los martes son suyos',
   'Entre el trabajo y la casa, Gonzalo no encontraba una hora para su padre. Dejó de buscar huecos y priorizó: los martes a las siete, pasara lo que pasara. Llevan catorce meses y ya nadie pregunta si habrá martes.',
   'A ver si saco un rato esta semana.', 'Lo he priorizado: los martes a las siete.', 2),
  ('6064f214-1ddb-49fa-b87e-0ef6dbe15fd2', 'entrevista', 'practica', '¿Qué harías el primer mes?',
   'Ámbar no prometió arreglarlo todo: «El primer mes priorizo dos cosas: entender por qué se van los clientes y arreglar el aviso de cobro. Lo demás lo miro en el segundo». Le dijeron que era la primera respuesta con orden del día.',
   'Pues me pondría con todo lo que haga falta.', 'El primer mes priorizo dos cosas.', 3);

