insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('05b3f214-bb96-4fc6-bea3-5f9128094d16', 'trabajo', 'practica', 'Una pregunta por persona',
   'El informe estaba parado porque faltaban cifras de cuatro áreas. En vez de convocar a todos, Ámbar mandó un correo con una sola pregunta a cada responsable: «Necesito recabar un dato tuyo antes del jueves». El jueves tenía los cuatro.',
