insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('9c1d9152-dfea-4528-8fbe-a2a92e462fe6', 'trabajo', 'practica', 'Tres páginas, dos ideas',
   'Otilia leyó el informe con un lápiz y marcó cuatro párrafos. «No están mal; son redundantes», dijo. «Esto lo dice el titular, y esto lo dice el gráfico». Quedaron dos páginas, y por fin alguien las leyó enteras.',
   'Esto ya lo habías dicho antes, ¿no?', 'No está mal: es redundante.', 1),
  ('9c1d9152-dfea-4528-8fbe-a2a92e462fe6', 'social', 'social', 'El cartel del portal',
   'En la reunión de vecinos discutían el cartel de la obra. Ivo señaló las dos últimas líneas: «Son redundantes, repiten el horario de arriba». Lo quitaron, el cartel cupo en media hoja y por fin se leía desde el ascensor.',
   'Eso está repetido, creo.', 'Esas dos líneas son redundantes.', 2),
  ('9c1d9152-dfea-4528-8fbe-a2a92e462fe6', 'entrevista', 'practica', 'Un currículo de una hoja',
   'Amalia tenía tres páginas y una amiga con tijeras. «Mira, esto es redundante: si dices que dirigiste el equipo, no hace falta repetir que coordinabas al equipo». Quedó una hoja, y en la entrevista le preguntaron por todo lo que había en ella.',
   'Es que quiero que se note todo lo que hice.', 'Esto es redundante: ya lo dijiste arriba.', 3);

