insert into public.readings (word_id, scene, conversation_type, title, body, before_phrase, after_phrase, position)
values
  ('7f463a54-e948-402d-9001-1e7a0de03bc9', 'trabajo', 'practica', 'La caja sobre la mesa',
   'Después de veinte diapositivas, la sala seguía fría. Otilia abrió una caja y puso la pieza encima de la mesa: «Esto es lo tangible; el resto es cómo llegamos hasta aquí». Tres personas se levantaron para tocarla y la reunión cambió de sitio.',
   'Te enseño unos gráficos y ya lo verás.', 'Esto es lo tangible; lo demás es el camino.', 1),
  ('7f463a54-e948-402d-9001-1e7a0de03bc9', 'familia', 'emocional', 'La bici del escaparate',
   '«¿Para qué ahorro?», preguntó su hijo por cuarta vez. Gonzalo dejó la charla y lo llevó a la tienda: «Faltan once semanas para esta». Volvieron andando y el niño empezó a contar las semanas. El objetivo se había vuelto tangible.',
   'Ahorrar es bueno, ya lo entenderás.', 'Faltan once semanas para algo tangible.', 2),
  ('7f463a54-e948-402d-9001-1e7a0de03bc9', 'entrevista', 'practica', 'Un número, no un adjetivo',
   'A Ámbar le pidieron un ejemplo de su trabajo y evitó los adjetivos: «Bajamos de nueve días a cuatro en el plazo de respuesta, y eso se mide cada lunes». Le dijeron que era el primer dato tangible de toda la mañana.',
   'Soy muy resolutiva, de verdad.', 'Te doy algo tangible: de nueve días a cuatro.', 3);

